create extension if not exists pgcrypto;
create type public.family_role as enum ('parent','student');
create type public.application_status as enum ('not_started','researching','in_progress','submitted','accepted','waitlisted','deferred','rejected','withdrawn');
create type public.opportunity_status as enum ('saved','researching','in_progress','submitted','awarded','not_awarded','declined');
create type public.task_status as enum ('todo','in_progress','done','cancelled');
create table public.families(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table public.family_members(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role public.family_role not null,display_name text not null,created_at timestamptz not null default now(),unique(family_id,user_id));
create table public.students(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id) on delete cascade,display_name text not null,graduation_year integer not null check(graduation_year between 2026 and 2045),school_name text,gpa numeric(4,2) check(gpa between 0 and 5),intended_major text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,family_id));
create table public.colleges(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id) on delete cascade,name text not null,location text,website_url text,admissions_url text,estimated_annual_cost numeric(12,2),notes text,created_at timestamptz not null default now(),unique(id,family_id));
create table public.college_interests(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id) on delete cascade,student_id uuid not null, college_id uuid not null,interest_level text not null default 'exploring' check(interest_level in('exploring','interested','target','safety','top_choice')),notes text,created_at timestamptz not null default now(),unique(student_id,college_id),foreign key(student_id,family_id) references public.students(id,family_id) on delete cascade,foreign key(college_id,family_id) references public.colleges(id,family_id) on delete cascade);
create table public.applications(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id) on delete cascade,student_id uuid not null,college_id uuid not null,application_type text not null default 'undergraduate',status public.application_status not null default 'not_started',application_deadline date,submitted_at timestamptz,decision_date date,portal_url text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(student_id,college_id,application_type),unique(id,family_id),foreign key(student_id,family_id) references public.students(id,family_id) on delete cascade,foreign key(college_id,family_id) references public.colleges(id,family_id) on delete cascade);
create table public.application_requirements(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id) on delete cascade,application_id uuid not null,title text not null,requirement_type text not null default 'other',due_date date,is_complete boolean not null default false,completed_at timestamptz,notes text,created_at timestamptz not null default now(),foreign key(application_id,family_id) references public.applications(id,family_id) on delete cascade);
create table public.scholarships(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id) on delete cascade,name text not null,sponsor text,description text,award_amount numeric(12,2),renewable boolean not null default false,eligibility_notes text,application_url text,opens_on date,deadline date,source_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,family_id));
create table public.scholarship_applications(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id) on delete cascade,scholarship_id uuid not null,student_id uuid not null,status public.opportunity_status not null default 'saved',submitted_at timestamptz,decision_date date,awarded_amount numeric(12,2),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(scholarship_id,student_id),unique(id,family_id),foreign key(scholarship_id,family_id) references public.scholarships(id,family_id) on delete cascade,foreign key(student_id,family_id) references public.students(id,family_id) on delete cascade);
create table public.tasks(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id) on delete cascade,student_id uuid,title text not null,description text,category text not null default 'general',due_date date,status public.task_status not null default 'todo',priority text not null default 'normal' check(priority in('low','normal','high','urgent')),assigned_to uuid references auth.users(id) on delete set null,related_application_id uuid,related_scholarship_application_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(student_id,family_id) references public.students(id,family_id) on delete set null,foreign key(related_application_id,family_id) references public.applications(id,family_id) on delete set null,foreign key(related_scholarship_application_id,family_id) references public.scholarship_applications(id,family_id) on delete set null);
create table public.awards(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id) on delete cascade,student_id uuid not null,college_id uuid,scholarship_application_id uuid,award_name text not null,award_type text not null default 'scholarship',amount numeric(12,2) not null check(amount>=0),is_renewable boolean not null default false,academic_year text,notes text,created_at timestamptz not null default now(),foreign key(student_id,family_id) references public.students(id,family_id) on delete cascade,foreign key(college_id,family_id) references public.colleges(id,family_id) on delete set null,foreign key(scholarship_application_id,family_id) references public.scholarship_applications(id,family_id) on delete set null);
create index students_family_idx on public.students(family_id);
create index applications_family_deadline_idx on public.applications(family_id,application_deadline);
create index scholarships_family_deadline_idx on public.scholarships(family_id,deadline);
create index tasks_family_due_idx on public.tasks(family_id,due_date);
create index scholarship_apps_student_idx on public.scholarship_applications(student_id,status);
create or replace function public.is_family_member(target_family_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.family_members fm where fm.family_id=target_family_id and fm.user_id=(select auth.uid())); $$;
revoke all on function public.is_family_member(uuid) from public;
grant execute on function public.is_family_member(uuid) to authenticated;
alter table public.families enable row level security;
alter table public.family_members enable row level security;
alter table public.students enable row level security;
alter table public.colleges enable row level security;
alter table public.college_interests enable row level security;
alter table public.applications enable row level security;
alter table public.application_requirements enable row level security;
alter table public.scholarships enable row level security;
alter table public.scholarship_applications enable row level security;
alter table public.tasks enable row level security;
alter table public.awards enable row level security;
create policy "Members can read their families" on public.families for select to authenticated using(public.is_family_member(id));
create policy "Members can read family membership" on public.family_members for select to authenticated using(public.is_family_member(family_id));
create policy "Family members manage students" on public.students for all to authenticated using(public.is_family_member(family_id)) with check(public.is_family_member(family_id));
create policy "Family members manage colleges" on public.colleges for all to authenticated using(public.is_family_member(family_id)) with check(public.is_family_member(family_id));
create policy "Family members manage college interests" on public.college_interests for all to authenticated using(public.is_family_member(family_id)) with check(public.is_family_member(family_id));
create policy "Family members manage applications" on public.applications for all to authenticated using(public.is_family_member(family_id)) with check(public.is_family_member(family_id));
create policy "Family members manage application requirements" on public.application_requirements for all to authenticated using(public.is_family_member(family_id)) with check(public.is_family_member(family_id));
create policy "Family members manage scholarships" on public.scholarships for all to authenticated using(public.is_family_member(family_id)) with check(public.is_family_member(family_id));
create policy "Family members manage scholarship applications" on public.scholarship_applications for all to authenticated using(public.is_family_member(family_id)) with check(public.is_family_member(family_id));
create policy "Family members manage tasks" on public.tasks for all to authenticated using(public.is_family_member(family_id)) with check(public.is_family_member(family_id));
create policy "Family members manage awards" on public.awards for all to authenticated using(public.is_family_member(family_id)) with check(public.is_family_member(family_id));
